/* Generated by build-web.py. Both app scopes use the same complete build. */
const CACHE_NAME = 'tetris-web-__BUILD_ID__';
const ROOT = new URL(__ROOT_PATH__, self.location.href);
const PRECACHE = __PRECACHE__;

self.addEventListener('install', event => {
    event.waitUntil(caches.open(CACHE_NAME).then(async cache => {
        await cache.addAll(PRECACHE.map(path => new Request(new URL(path, ROOT), { cache: 'reload' })));
        await self.skipWaiting();
    }));
});
self.addEventListener('activate', event => {
    event.waitUntil(self.clients.claim());
});
self.addEventListener('fetch', event => {
    const url = new URL(event.request.url);
    if (event.request.method !== 'GET' || url.origin !== ROOT.origin || !url.pathname.startsWith(ROOT.pathname)) return;
    event.respondWith((async () => {
        const cache = await caches.open(CACHE_NAME);
        try {
            const response = await fetch(event.request, { cache: 'no-cache' });
            if (response.ok) await cache.put(event.request, response.clone());
            return response;
        } catch (error) {
            // Never search all caches: a native pre-theme file can have the
            // same old URL. Only this build is a valid offline fallback.
            const hit = await cache.match(event.request);
            if (hit) return hit;
            if (event.request.mode === 'navigate') {
                const page = new URL(url.pathname.endsWith('/') ? url.pathname + 'index.html' : url.pathname, url);
                const html = await cache.match(page);
                if (html) return html;
            }
            throw error;
        }
    })());
});
